<template>
  <div class="rc-root">
    <!-- ── HERO ──────────────────────────────────────────────────────── -->
    <header class="rc-hero">
      <div class="rc-hero__inner">
        <div class="rc-hero__left">
          <h1 class="rc-hero__title">Recruitment Manager</h1>
          <p class="rc-hero__sub">
            Manage vacancies, track applications, coordinate PSC submissions and
            issue appointments.
          </p>
          <div class="rc-hero__actions">
            <v-btn color="orange darken-1" dark @click="advertiseVacancy">
              <v-icon left small>mdi-plus</v-icon>Advertise Vacancy
            </v-btn>
          </div>
        </div>
        <div class="rc-hero__right">
          <div class="rc-stat" v-for="s in heroStats" :key="s.label">
            <div class="rc-stat__num">{{ s.value }}</div>
            <div class="rc-stat__label">{{ s.label }}</div>
          </div>
        </div>
      </div>
    </header>

    <!-- ── MAIN GRID ─────────────────────────────────────────────────── -->
    <main class="rc-body">
      <!-- Active Vacancies Table -->
      <v-card outlined class="rc-card--wide">
        <v-card-title
          class="d-flex align-center justify-space-between py-3 px-4"
          style="border-bottom:1.5px solid #e7e5e4;"
        >
          <div class="d-flex align-center" style="gap:10px;">
            <v-chip
              x-small
              color="orange lighten-4"
              text-color="orange darken-2"
              >Active</v-chip
            >
            <span
              class="text-h6 font-weight-bold"
              style="font-size:16px!important;"
              >Advertised Vacancies</span
            >
          </div>
          <v-btn small outlined @click="advertiseVacancy">
            <v-icon left x-small>mdi-plus</v-icon>New
          </v-btn>
        </v-card-title>

        <!-- ── Filters ─────────────────────────────────────────────── -->
        <v-card-text class="pb-1 pt-3">
          <v-row dense>
            <v-col cols="12" sm="6" md="3">
              <v-text-field
                v-model="filter.position"
                label="Search designation"
                dense
                outlined
                hide-details
                clearable
                prepend-inner-icon="mdi-magnify"
                class="ma-1"
                @input="onFilterChange"
                @click:clear="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="6" md="2">
              <v-menu
                v-model="filterStartMenu"
                :close-on-content-click="false"
                offset-y
                max-width="290"
              >
                <template v-slot:activator="{ on }">
                  <v-text-field
                    :value="
                      filter.startDate ? formatDate(filter.startDate) : ''
                    "
                    label="From date"
                    dense
                    outlined
                    hide-details
                    clearable
                    readonly
                    prepend-inner-icon="mdi-calendar"
                    class="ma-1"
                    v-on="on"
                    @click:clear="
                      filter.startDate = null;
                      onFilterChange();
                    "
                  />
                </template>
                <v-date-picker
                  v-model="filter.startDate"
                  no-title
                  scrollable
                  @input="
                    filterStartMenu = false;
                    onFilterChange();
                  "
                />
              </v-menu>
            </v-col>
            <v-col cols="12" sm="6" md="2">
              <v-menu
                v-model="filterEndMenu"
                :close-on-content-click="false"
                offset-y
                max-width="290"
              >
                <template v-slot:activator="{ on }">
                  <v-text-field
                    :value="filter.endDate ? formatDate(filter.endDate) : ''"
                    label="To date"
                    dense
                    outlined
                    hide-details
                    clearable
                    readonly
                    prepend-inner-icon="mdi-calendar"
                    class="ma-1"
                    v-on="on"
                    @click:clear="
                      filter.endDate = null;
                      onFilterChange();
                    "
                  />
                </template>
                <v-date-picker
                  v-model="filter.endDate"
                  no-title
                  scrollable
                  @input="
                    filterEndMenu = false;
                    onFilterChange();
                  "
                />
              </v-menu>
            </v-col>
            <v-col cols="12" sm="auto" class="d-flex align-center">
              <v-btn
                :color="filter.openOnly ? 'teal darken-1' : 'grey'"
                :outlined="!filter.openOnly"
                :dark="filter.openOnly"
                small
                class="ma-1"
                title="Show only currently open advertisements"
                @click="
                  filter.openOnly = !filter.openOnly;
                  onFilterChange();
                "
              >
                <v-icon small left>mdi-clock-outline</v-icon>
                Currently Open
              </v-btn>
            </v-col>
            <v-col cols="12" sm="auto" class="d-flex align-center">
              <v-btn
                :color="filter.hideClosedHiring ? 'teal darken-1' : 'grey'"
                :outlined="!filter.hideClosedHiring"
                :dark="filter.hideClosedHiring"
                small
                class="ma-1"
                title="Hide advertisements with hiring closed"
                @click="
                  filter.hideClosedHiring = !filter.hideClosedHiring;
                  onFilterChange();
                "
              >
                <v-icon small left>mdi-account-lock-outline</v-icon>
                Hide Closed Hiring
              </v-btn>
            </v-col>
            <v-col cols="12" sm="auto" class="d-flex align-center">
              <v-btn
                v-if="hasActiveFilters"
                text
                small
                color="red darken-1"
                class="ma-1"
                @click="resetFilters"
              >
                <v-icon small left>mdi-close</v-icon>
                Clear filters
              </v-btn>
            </v-col>
          </v-row>
        </v-card-text>

        <!-- ── Data table ──────────────────────────────────────────── -->
        <v-data-table
          :headers="tableHeaders"
          :items="vacancies"
          :loading="loadingVacancies"
          loading-text="Loading vacancies…"
          no-data-text="No vacancies match the current filters"
          :server-items-length="totalVacancies"
          :options.sync="tableOptions"
          :footer-props="{
            'items-per-page-options': [10, 15, 25, 50],
            'items-per-page-text': 'Rows per page',
          }"
          class="elevation-0"
        >
          <!-- Position + supporting badge -->
          <template #[`item.designation`]="{ item }">
            <span class="font-weight-bold">{{ item.designation }}</span>
            <v-chip
              v-if="item.type === 'supporting'"
              x-small
              color="teal lighten-5"
              text-color="teal darken-2"
              class="ml-1"
              >Supporting Staff</v-chip
            >
          </template>

          <!-- Employment category -->
          <template #[`item.employmentCategory`]="{ item }">
            <span class="grey--text text--darken-1 body-2">
              {{
                (item.employmentCategory && item.employmentCategory.display) ||
                  "—"
              }}
            </span>
          </template>

          <!-- Grade -->
          <template #[`item.grade`]="{ item }">
            <v-chip
              v-if="item.grade"
              x-small
              :color="
                gradeClass(item.grade) === 'lower'
                  ? 'indigo lighten-5'
                  : 'orange lighten-5'
              "
              :text-color="
                gradeClass(item.grade) === 'lower'
                  ? 'indigo darken-2'
                  : 'orange darken-2'
              "
              >{{ item.grade }}</v-chip
            >
            <span v-else class="grey--text">—</span>
          </template>

          <!-- Dates -->
          <template #[`item.advertisedDate`]="{ item }">
            <span
              class="caption grey--text text--darken-1"
              style="font-family:monospace;"
              >{{ formatDate(item.advertisedDate) }}</span
            >
          </template>
          <template #[`item.openDate`]="{ item }">
            <span
              class="caption grey--text text--darken-1"
              style="font-family:monospace;"
              >{{ item.openDate ? formatDate(item.openDate) : "—" }}</span
            >
          </template>

          <!-- Closing date -->
          <template #[`item.closingDate`]="{ item }">
            <span
              :class="
                isClosingSoon(item.closingDate)
                  ? 'error--text font-weight-medium'
                  : 'caption grey--text text--darken-1'
              "
              style="font-family:monospace;"
            >
              {{ formatDate(item.closingDate) }}
            </span>
            <v-chip
              v-if="isClosingSoon(item.closingDate)"
              x-small
              color="red lighten-5"
              text-color="red darken-1"
              class="ml-1"
              >Soon</v-chip
            >
          </template>

          <!-- Application count -->
          <template #[`item.applicationsCount`]="{ item }">
            <span class="font-weight-bold" style="font-family:monospace;">{{
              item.applicationsCount
            }}</span>
          </template>

          <!-- Status -->
          <template #[`item.statusKey`]="{ item }">
            <v-chip
              x-small
              :color="
                {
                  open: 'green lighten-5',
                  closed: 'grey lighten-3',
                  pending: 'orange lighten-5',
                }[advertStatus(item).key]
              "
              :text-color="
                {
                  open: 'green darken-2',
                  closed: 'grey darken-1',
                  pending: 'orange darken-2',
                }[advertStatus(item).key]
              "
              >{{ advertStatus(item).label }}</v-chip
            >
          </template>

          <!-- Hiring status (separate from application open/closed above:
               an advert can be closed to new applications while hiring is
               still ongoing, or vice versa once hiring is explicitly closed) -->
          <template #[`item.hiringStatus`]="{ item }">
            <v-chip
              x-small
              :color="
                {
                  ongoing: 'green lighten-5',
                  pending: 'orange lighten-5',
                  closed: 'red lighten-5',
                }[hiringStatusCode(item)]
              "
              :text-color="
                {
                  ongoing: 'green darken-2',
                  pending: 'orange darken-2',
                  closed: 'red darken-1',
                }[hiringStatusCode(item)]
              "
              >{{ hiringStatusLabel(item) }}</v-chip
            >
          </template>

          <!-- Row actions -->
          <template #[`item.actions`]="{ item }">
            <v-menu offset-y left :close-on-content-click="false">
              <template v-slot:activator="{ on, attrs }">
                <v-btn icon small v-bind="attrs" v-on="on" @click.stop>
                  <v-icon small>mdi-dots-vertical</v-icon>
                </v-btn>
              </template>
              <v-list dense>
                <v-list-item @click="openVacancy(item)">
                  <v-list-item-icon class="mr-2">
                    <v-icon small>mdi-eye-outline</v-icon>
                  </v-list-item-icon>
                  <v-list-item-title>View Advertisement</v-list-item-title>
                </v-list-item>
                <v-list-item
                  :disabled="hiringStatusCode(item) === 'closed'"
                  :title="
                    hiringStatusCode(item) === 'closed'
                      ? 'Hiring is closed for this advertisement'
                      : undefined
                  "
                  @click="editVacancy(item)"
                >
                  <v-list-item-icon class="mr-2">
                    <v-icon small>mdi-pencil-outline</v-icon>
                  </v-list-item-icon>
                  <v-list-item-title>
                    {{ hiringStatusCode(item) === "closed" ? "Edit Advertisement (Hiring Closed)" : "Edit Advertisement" }}
                  </v-list-item-title>
                </v-list-item>
                <v-list-item @click="viewApplications(item)">
                  <v-list-item-icon class="mr-2">
                    <v-icon small>mdi-account-group-outline</v-icon>
                  </v-list-item-icon>
                  <v-list-item-title>View Applications</v-list-item-title>
                </v-list-item>
                <close-hiring-button
                  :advert-id="item.advertId || item.id"
                  :vacancies="item.vacancies"
                  :label="item.designation"
                  :disabled="hiringStatusCode(item) === 'closed'"
                  @closed="loadVacancies(true)"
                >
                  <template #activator="{ open, disabled }">
                    <v-list-item :disabled="disabled" @click="open">
                      <v-list-item-icon class="mr-2">
                        <v-icon small color="error"
                          >mdi-account-lock-outline</v-icon
                        >
                      </v-list-item-icon>
                      <v-list-item-title class="error--text">
                        {{ disabled ? "Hiring Closed" : "Close Hiring" }}
                      </v-list-item-title>
                    </v-list-item>
                  </template>
                </close-hiring-button>
              </v-list>
            </v-menu>
          </template>
        </v-data-table>
      </v-card>
    </main>
  </div>
</template>

<script>
const ADV_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/vacancy-advertisement-profile";

import CloseHiringButton from "../shared/CloseHiringButton.vue";

export default {
  name: "RecruitmentLanding",
  components: { CloseHiringButton },
  props: ["queries"],

  data() {
    return {
      // ── Vacancy list (loaded from backend) ──────────────────────────
      vacancies: [],
      loadingVacancies: false,

      // ── Filters ─────────────────────────────────────────────────────
      filter: {
        position: "", // designation text search
        startDate: null, // advert start date ≥ this
        endDate: null, // advert end date ≤ this
        openOnly: false, // start ≤ today AND end ≥ today
        hideClosedHiring: true, // exclude advertisements with hiring-status = closed
      },
      filterDebounce: null,

      // ── Pagination (owned by v-data-table via options.sync) ─────────
      tableOptions: { page: 1, itemsPerPage: 10 },
      prevPage: 0,
      link: [],
      totalVacancies: 0,
      filterStartMenu: false,
      filterEndMenu: false,

      tableHeaders: [
        { text: "", value: "actions", sortable: false, width: "50px" },
        { text: "Position", value: "designation", width: "180px" },
        { text: "Employment Category", value: "employmentCategory" },
        { text: "Facility", value: "facility" },
        { text: "Grade", value: "grade" },
        { text: "Vacancies", value: "vacancies", align: "center" },
        { text: "Advertised", value: "advertisedDate" },
        { text: "Open Date", value: "openDate" },
        { text: "Closes", value: "closingDate" },
        { text: "Applications", value: "applicationsCount", align: "center" },
        { text: "Application Status", value: "statusKey", sortable: false },
        { text: "Hiring Status", value: "hiringStatus", sortable: false },
      ],

      // ── Side-panel data ─────────────────────────────────────────────
      pscQueue: [],
      pendingAppointments: [],
    };
  },

  computed: {
    hasActiveFilters() {
      return (
        !!this.filter.position ||
        !!this.filter.startDate ||
        !!this.filter.endDate ||
        this.filter.openOnly ||
        this.filter.hideClosedHiring
      );
    },

    heroStats() {
      const total = this.vacancies.length;
      const today = new Date().toISOString().split("T")[0];
      const openCount = this.vacancies.filter(
        (v) => v.openDate <= today && v.closingDate >= today,
      ).length;
      const totalApps = this.vacancies.reduce(
        (s, v) => s + (v.applicationsCount || 0),
        0,
      );
      const pscPending = this.pscQueue.filter(
        (p) => p.pscStatus === "submitted",
      ).length;

      return [
        {
          label: "Active Vacancies",
          value: openCount,
          pct: total ? (openCount / total) * 100 : 0,
          color: "#f97316",
        },
        {
          label: "Total Applications",
          value: totalApps,
          pct: Math.min((totalApps / 200) * 100, 100),
          color: "#6366f1",
        },
        {
          label: "Pending PSC",
          value: pscPending,
          pct: this.pscQueue.length
            ? (pscPending / this.pscQueue.length) * 100
            : 0,
          color: "#7c3aed",
        },
        {
          label: "Issue Appointment",
          value: this.pendingAppointments.length,
          pct: Math.min(this.pendingAppointments.length * 20, 100),
          color: "#0d9488",
        },
      ];
    },

    closingThisWeek() {
      const now = new Date();
      const weekAhead = new Date(now.getTime() + 7 * 86400000);
      return this.vacancies.filter((v) => {
        const d = new Date(v.closingDate);
        return d >= now && d <= weekAhead;
      });
    },
  },

  watch: {
    tableOptions: {
      handler() {
        this.loadVacancies(false);
      },
      deep: true,
    },
  },

  async mounted() {
    await this.loadVacancies(true);
    // PSC queue and pending appointments can be loaded in parallel later
    // await Promise.all([this.loadPscQueue(), this.loadPendingAppointments()]);
  },

  methods: {
    // ── Load advertised positions from FHIR ─────────────────────────
    buildVacancyUrl() {
      const params = new URLSearchParams({
        _profile: ADV_PROFILE,
        _count: this.tableOptions.itemsPerPage,
        _total: "accurate",
        _sort: "-_lastUpdated",
      });
      params.append("_include", "Basic:position");
      params.append("_include:iterate", "Basic:posdesignation");
      params.append("_include:iterate", "Basic:facility");
      params.append("_include:iterate", "Basic:salarygrade");

      if (this.filter.position.trim()) {
        params.set("name:contains", this.filter.position.trim());
      }
      if (this.filter.startDate) {
        params.set("startdate", `ge${this.filter.startDate}`);
      }
      if (this.filter.endDate) {
        params.set("enddate", `le${this.filter.endDate}`);
      }
      if (this.filter.openOnly) {
        const today = new Date().toISOString().split("T")[0];
        params.set("startdate", `le${today}`);
        params.set("enddate", `ge${today}`);
      }
      // hideClosedHiring is applied client-side after the fetch (see
      // loadVacancies) rather than via a server-side search param — the
      // hiring-status SearchParameter needs the IG rebuilt/reindexed
      // before the FHIR server can filter on it reliably.
      return `/fhir/Basic?${params}`;
    },

    async loadVacancies(restart) {
      if (this.loadingVacancies) return;
      this.loadingVacancies = true;
      if (restart) {
        this.tableOptions.page = 1;
        this.link = [];
        this.prevPage = 0;
      }
      try {
        const { page } = this.tableOptions;
        let url;

        if (page === 1 || this.link.length === 0) {
          url = this.buildVacancyUrl();
        } else if (page === this.prevPage + 1) {
          const next = this.link.find((l) => l.relation === "next");
          url = next
            ? next.url.substring(next.url.indexOf("/fhir/"))
            : this.buildVacancyUrl();
        } else if (page === this.prevPage - 1) {
          const prev = this.link.find((l) => l.relation === "previous");
          url = prev
            ? prev.url.substring(prev.url.indexOf("/fhir/"))
            : this.buildVacancyUrl();
        } else {
          url = this.buildVacancyUrl();
        }

        const res = await fetch(url);
        const data = await res.json();

        this.link = data.link || [];
        this.prevPage = page;

        const extValue = (resource, url, key) => {
          const ext = (resource.extension || []).find((e) => e.url === url);
          return ext ? ext[key] : null;
        };

        const EXT = {
          NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
          POSITION:
            "http://ihris.org/fhir/StructureDefinition/position-reference",
          START: "http://ihris.org/fhir/StructureDefinition/start-date",
          END: "http://ihris.org/fhir/StructureDefinition/end-date",
          MAX:
            "http://ihris.org/fhir/StructureDefinition/maximum-practitioners",
          DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
          DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
          EMP_CAT:
            "http://ihris.org/fhir/StructureDefinition/employment-category",
          FACILITY: "http://ihris.org/fhir/StructureDefinition/facility",
          GRADE: "http://ihris.org/fhir/StructureDefinition/salary-grade",
          EVENT_DATE: "http://ihris.org/fhir/StructureDefinition/event-date",
          HIRING_STATUS:
            "http://ihris.org/fhir/StructureDefinition/hiring-status",
        };

        const allEntries = data.entry || [];

        // Adverts are search matches; positions/designations/facilities/grades are includes
        const advertEntries = allEntries.filter(
          (e) => e.search && e.search.mode === "match",
        );
        const includedEntries = allEntries.filter(
          (e) => !e.search || e.search.mode === "include",
        );

        // Build lookups from included resources
        const positionByRef = {};
        const designationByRef = {};
        const facilityNameById = {};
        const gradeNameById = {};

        for (const e of includedEntries) {
          const r = e.resource;
          if (!r) continue;
          if (r.resourceType === "Location") {
            if (r.name) facilityNameById[r.id] = r.name;
          } else if (r.resourceType === "Basic") {
            const profiles = (r.meta && r.meta.profile) || [];
            if (
              profiles.includes(
                "http://ihris.org/fhir/StructureDefinition/position-profile",
              )
            ) {
              positionByRef["Basic/" + r.id] = r;
            } else if (
              profiles.includes(
                "http://ihris.org/fhir/StructureDefinition/ls-designation-profile",
              )
            ) {
              designationByRef["Basic/" + r.id] = r;
            } else {
              // Grade or other — key by name extension presence
              const name = extValue(r, EXT.NAME, "valueString");
              if (name) gradeNameById[r.id] = name;
            }
          }
        }

        const fromBundle = advertEntries.map((e) => {
          const r = e.resource;
          const posRef = extValue(r, EXT.POSITION, "valueReference");
          const position =
            posRef && posRef.reference ? positionByRef[posRef.reference] : null;

          const designationRef = position
            ? extValue(position, EXT.DESIGNATION, "valueReference")
            : null;
          const designationRes =
            designationRef && designationRef.reference
              ? designationByRef[designationRef.reference]
              : null;
          const designationName = designationRes
            ? extValue(designationRes, EXT.NAME, "valueString")
            : null;

          const departmentCoding = position
            ? extValue(position, EXT.DEPARTMENT, "valueCoding")
            : null;
          const facilityRef = position
            ? extValue(position, EXT.FACILITY, "valueReference")
            : null;
          const gradeRef = position
            ? extValue(position, EXT.GRADE, "valueReference")
            : null;
          const facilityId =
            facilityRef &&
            facilityRef.reference &&
            facilityRef.reference.startsWith("Location/")
              ? facilityRef.reference.split("/")[1]
              : null;
          const gradeId =
            gradeRef &&
            gradeRef.reference &&
            gradeRef.reference.startsWith("Basic/")
              ? gradeRef.reference.split("/")[1]
              : null;

          const empCatCoding = extValue(r, EXT.EMP_CAT, "valueCoding");
          const hiringStatusCoding = extValue(
            r,
            EXT.HIRING_STATUS,
            "valueCoding",
          );

          return {
            id: r.id,
            advertId: r.id,
            designation:
              designationName || extValue(r, EXT.NAME, "valueString") || "",
            department:
              (departmentCoding &&
                (departmentCoding.display || departmentCoding.code)) ||
              "",
            employmentCategory: empCatCoding || null,
            hiringStatus: hiringStatusCoding || null,
            facility:
              (facilityId && facilityNameById[facilityId]) ||
              (facilityRef && facilityRef.display) ||
              "",
            grade:
              (gradeId && gradeNameById[gradeId]) ||
              (gradeRef && gradeRef.display) ||
              "",
            vacancies: Number(extValue(r, EXT.MAX, "valueInteger") || 0),
            advertisedDate: extValue(r, EXT.EVENT_DATE, "valueDate") || null,
            openDate: extValue(r, EXT.START, "valueDate") || null,
            closingDate: extValue(r, EXT.END, "valueDate") || null,
            applicationsCount: 0,
            stage: "advertised",
            type: "regular",
            positionRef: (posRef && posRef.reference) || null,
          };
        });

        const visible = this.filter.hideClosedHiring
          ? fromBundle.filter((v) => this.hiringStatusCode(v) !== "closed")
          : fromBundle;

        this.totalVacancies = data.total || fromBundle.length;
        this.vacancies = visible;
        this.loadApplicationCounts();
      } catch (err) {
        console.error("loadVacancies error", err);
        this.vacancies = [];
      } finally {
        this.loadingVacancies = false;
      }
    },

    // ── Fetch application count per advert ───────────────────────────
    async loadApplicationCounts() {
      const APP_PROFILE =
        "http://ihris.org/fhir/StructureDefinition/application-profile";
      const vacancies = this.vacancies;
      await Promise.all(
        vacancies.map(async (v) => {
          try {
            const params = new URLSearchParams({
              _profile: APP_PROFILE,
              advertisedvacancy: "Basic/" + v.id,
              _count: 0,
              _total: "accurate",
            });
            const res = await fetch("/fhir/Basic?" + params.toString());
            if (!res.ok) return;
            const bundle = await res.json();
            // Find the vacancy in the current list (may have changed pages)
            const target = this.vacancies.find((x) => x.id === v.id);
            if (target) {
              this.$set(target, "applicationsCount", bundle.total || 0);
            }
          } catch (e) {
            // Non-fatal – count stays 0
          }
        }),
      );
    },

    // ── Filters ─────────────────────────────────────────────────────
    onFilterChange() {
      clearTimeout(this.filterDebounce);
      this.filterDebounce = setTimeout(() => {
        this.loadVacancies(true);
      }, 400);
    },

    resetFilters() {
      this.filter = {
        position: "",
        startDate: null,
        endDate: null,
        openOnly: false,
        hideClosedHiring: true,
      };
      this.loadVacancies(true);
    },

    // ── Navigation ───────────────────────────────────────────────────
    advertiseVacancy() {
      this.$router.push({
        path: "/custom/advertise-position",
        query: { path: "/lesotho/components/recruitment" },
      });
    },
    editVacancy(v) {
      if (this.hiringStatusCode(v) === "closed") return;
      this.$router.push({
        path: "/custom/advertise-position",
        query: {
          path: "/lesotho/components/recruitment",
          advert: v.advertId || v.id,
        },
      });
    },
    openVacancy(v) {
      this.$router.push({
        path: "/custom/vacancy-detail",
        query: {
          path: "/lesotho/components/recruitment",
          id: v.advertId || v.id,
        },
      });
    },
    viewApplications(v) {
      this.$router.push({
        path: "/custom/applicant-list",
        query: {
          path: "/lesotho/components/recruitment",
          advertId: v.advertId || v.id,
        },
      });
    },
    advanceStage(v) {
      this.$emit("navigate", "advance-stage", { id: v.advertId || v.id });
    },
    issueAppointment(a) {
      this.$emit("navigate", "issue-appointment", { id: a.id });
    },

    // ── Helpers ──────────────────────────────────────────────────────
    formatDate(d) {
      if (!d) return "—";
      return new Date(d).toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },
    isClosingSoon(d) {
      if (!d) return false;
      const diff = new Date(d) - new Date();
      return diff > 0 && diff < 7 * 86400000;
    },
    closingDay(d) {
      return d ? new Date(d).getDate() : "";
    },
    closingMonth(d) {
      return d
        ? new Date(d)
            .toLocaleDateString("en-GB", { month: "short" })
            .toUpperCase()
        : "";
    },
    gradeClass(g) {
      if (!g) return "default";
      return ["A", "B", "C", "D", "E", "F", "G"].includes(
        (g || "").toUpperCase(),
      )
        ? "lower"
        : "senior";
    },
    stageColor(stage) {
      const m = {
        advertised: "#0d9488",
        applications_closed: "#f97316",
        shortlisting: "#6366f1",
        psc_submitted: "#7c3aed",
        psc_endorsed: "#0d9488",
        appointment_pending: "#f97316",
        onboarding: "#0d9488",
      };
      return m[stage] || "#a8a29e";
    },
    stageName(stage) {
      const m = {
        advertised: "Advertised",
        applications_closed: "Apps Closed",
        shortlisting: "Shortlisting",
        psc_submitted: "PSC Submitted",
        psc_endorsed: "PSC Endorsed",
        appointment_pending: "Appt. Ready",
        onboarding: "Onboarding",
      };
      return m[stage] || stage;
    },
    advertStatus(v) {
      const today = new Date().toISOString().split("T")[0];
      if (v.openDate && v.openDate > today) {
        return { key: "pending", label: "Not Yet Open" };
      }
      if (v.closingDate && v.closingDate < today) {
        return { key: "closed", label: "Closed" };
      }
      return { key: "open", label: "Open" };
    },

    // Hiring status is independent of the open/closed-for-applications
    // status above — an advert can stop accepting applications while
    // hiring is still ongoing, or hiring can be explicitly closed (see
    // close-hiring) while the advert's own dates haven't expired yet.
    hiringStatusCode(v) {
      return v.hiringStatus?.code || "ongoing";
    },
    hiringStatusLabel(v) {
      return (
        v.hiringStatus?.display ||
        { ongoing: "Ongoing", pending: "Pending", closed: "Closed" }[
          this.hiringStatusCode(v)
        ] ||
        "Ongoing"
      );
    },

    pscStatusColor(s) {
      return (
        { submitted: "orange", endorsed: "teal", returned: "red" }[s] || "grey"
      );
    },
    pscChipColor(s) {
      const m = {
        submitted: { bg: "orange lighten-5", text: "orange darken-2" },
        endorsed: { bg: "teal lighten-5", text: "teal darken-2" },
        returned: { bg: "red lighten-5", text: "red darken-1" },
      };
      return m[s] || { bg: "grey lighten-3", text: "grey darken-1" };
    },
    pscStatusLabel(s) {
      return (
        {
          submitted: "Awaiting Review",
          endorsed: "Endorsed",
          returned: "Returned",
        }[s] || s
      );
    },
    initials(name) {
      return (name || "")
        .split(" ")
        .map((n) => n[0])
        .join("")
        .slice(0, 2)
        .toUpperCase();
    },
  },
};
</script>
